 private Alarm awaitNap(Fixture fixture,java.util.function.Predicate<Alarm> expected,String label){Alarm[] row={null};boolean[] ready={false};long end=SystemClock.elapsedRealtime()+5000;do{i.runOnMainSync(()->{try{row[0]=fixture.nap();ready[0]=expected.test(row[0]);}catch(java.util.NoSuchElementException pending){ready[0]=false;}});if(!ready[0])SystemClock.sleep(25);}while(!ready[0]&&SystemClock.elapsedRealtime()<end);assertTrue("Saved nap state after actual action: "+label,ready[0]);return row[0];}
 private void launch(int id)throws Exception{Instrumentation.ActivityMonitor m=i.addMonitor(NapActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,NapActivity.class).putExtra("id",id).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(NapActivity)m.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(m);}i.waitForIdleSync();text("Nap");}
 private void recreate(String expected)throws Exception{step="recreate: "+expected;Instrumentation.ActivityMonitor m=i.addMonitor(NapActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(NapActivity)m.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(m);}if(expected.equals("Nap"))exposeRecreatedHeader();text(expected);}
 private View nativeText(View root,String value){if(root instanceof android.widget.TextView&&value.contentEquals(((android.widget.TextView)root).getText()))return root;if(root instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)root;for(int n=0;n<group.getChildCount();n++){View found=nativeText(group.getChildAt(n),value);if(found!=null)return found;}}return null;}
 /** Restored errors deliberately reveal the settings/footer, so the real header can be offscreen. */
 private void exposeRecreatedHeader()throws Exception{
  CountDownLatch frame=new CountDownLatch(1);View[] owned=new View[2];long end=SystemClock.elapsedRealtime()+5000;
  while(owned[0]==null&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{View root=activity.getWindow().getDecorView(),title=nativeText(root,"Nap");if(activity.hasWindowFocus()&&root.isAttachedToWindow()&&root.isHardwareAccelerated()&&title!=null&&title.isLaidOut()){owned[0]=root;owned[1]=title;}});if(owned[0]==null)SystemClock.sleep(25);}
  assertNotNull("Focused recreated Nap with laid-out native header",owned[0]);i.waitForIdleSync();
  i.runOnMainSync(()->{View root=owned[0],title=owned[1];assertSame("Same recreated Nap decor",root,activity.getWindow().getDecorView());assertTrue(title.isAttachedToWindow());android.view.ViewParent parent=title.getParent();while(parent!=null&&!(parent instanceof android.widget.ScrollView))parent=parent.getParent();assertTrue("Header belongs to the actual Nap scroll page",parent instanceof android.widget.ScrollView);((android.widget.ScrollView)parent).scrollTo(0,0);root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();});
  assertTrue("Actual header frame committed",frame.await(5,TimeUnit.SECONDS));
  i.runOnMainSync(()->{assertSame(owned[0],activity.getWindow().getDecorView());assertTrue(activity.hasWindowFocus());assertTrue(owned[1].isAttachedToWindow());Rect bounds=new Rect();assertTrue("Recreated Nap header is visible",owned[1].getGlobalVisibleRect(bounds));assertEquals("Whole header height",owned[1].getHeight(),bounds.height());assertEquals("Whole header width",owned[1].getWidth(),bounds.width());});
 }
 private void text(String value){assertTrue(value,ui.wait(Until.hasObject(By.text(value)),5000));}
 private UiObject2 find(String text){UiObject2 object=ui.wait(Until.findObject(By.text(text)),1500);if(object==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));if(scroll.exists())try{scroll.scrollIntoView(new UiSelector().text(text));}catch(UiObjectNotFoundException failure){throw new AssertionError(failure);}object=ui.wait(Until.findObject(By.text(text)),2000);}assertNotNull(text,object);return object;}
 private void click(String text){step="click: "+text;find(text).click();ui.waitForIdle();}
 private void desc(String value){step="click description: "+value;UiObject2 object=ui.wait(Until.findObject(By.desc(value)),2500);assertNotNull(value,object);object.click();ui.waitForIdle();}
 private void finish(){i.runOnMainSync(activity::finish);i.waitForIdleSync();long end=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<end)SystemClock.sleep(50);assertTrue(activity.isDestroyed());}
 private void assertCompleteDeleteControl(){i.runOnMainSync(()->{View root=activity.getWindow().getDecorView(),row=root.findViewWithTag("nap-delete-row"),footer=root.findViewWithTag("nap-footer");assertNotNull("Deletion setting row exists",row);assertNotNull("Fixed Nap footer exists",footer);Rect visible=new Rect(),fixed=new Rect();assertTrue("Deletion row is visible",row.getGlobalVisibleRect(visible));assertEquals("Whole title/subtitle/switch row must be visible without a test scroll",row.getHeight(),visible.height());assertEquals(row.getWidth(),visible.width());assertTrue(footer.getGlobalVisibleRect(fixed));assertTrue("Setting must sit completely above fixed footer",visible.bottom<=fixed.top);android.widget.LinearLayout setting=(android.widget.LinearLayout)row;View control=setting.getChildAt(setting.getChildCount()-1);Rect switchBounds=new Rect();assertTrue(control.getGlobalVisibleRect(switchBounds));assertEquals("Switch must not be clipped",control.getHeight(),switchBounds.height());});}
 private void capture(String suffix)throws Exception{CountDownLatch frame=new CountDownLatch(1);boolean[] ready={false};long end=SystemClock.elapsedRealtime()+5000;while(!ready[0]&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{View v=activity.getWindow().getDecorView();if(activity.hasWindowFocus()&&v.isAttachedToWindow()&&v.isHardwareAccelerated()){v.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);v.invalidate();ready[0]=true;}});if(!ready[0])SystemClock.sleep(50);}assertTrue("Focused actual Nap window",ready[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));if(suffix.equals("permission-error")||suffix.equals("scheduler-error")||suffix.equals("tracking-required"))assertCompleteDeleteControl();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(ui.takeScreenshot(new File(folder,"nap-"+suffix+".png")));}
 private void captureFailure(Throwable failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());java.nio.file.Files.write(new File(folder,"nap-original-failure.txt").toPath(),("Step: "+step+"\n"+failure).getBytes(java.nio.charset.StandardCharsets.UTF_8));ui.takeScreenshot(new File(folder,"nap-original-failure.png"));ui.dumpWindowHierarchy(new File(folder,"nap-original-failure.xml"));}catch(Exception|AssertionError diagnostic){failure.addSuppressed(diagnostic);}}

 /** Drain the existing real reader owners before restoring the fixture database factory. */
 private void awaitSupportingReader(Class<?> type,Object owner,String name)throws Exception{
  java.lang.reflect.Field field=type.getDeclaredField(name);field.setAccessible(true);ExecutorService executor=(ExecutorService)field.get(owner);
  if(executor.isShutdown())assertTrue("Reader released: "+type.getSimpleName(),executor.awaitTermination(8,TimeUnit.SECONDS));else executor.submit(()->{}).get(8,TimeUnit.SECONDS);
 }
 private Activity supportingOwner(Class<? extends Activity> type)throws Exception{
  Activity[] found={null};long end=SystemClock.elapsedRealtime()+5000;
  while(found[0]==null&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{Activity owner=visibleActivity;if(owner!=null&&owner.getClass()==type&&!owner.isFinishing()&&!owner.isDestroyed()&&owner.hasWindowFocus()){View root=owner.getWindow().getDecorView();if(root.isAttachedToWindow()&&root.isLaidOut())found[0]=owner;}});if(found[0]==null)SystemClock.sleep(25);}
  assertNotNull("Actual focused "+type.getSimpleName(),found[0]);return found[0];
 }
 private Activity openSupporting(Intent intent,Class<? extends Activity> type)throws Exception{
  i.runOnMainSync(()->activity.startActivity(intent));i.waitForIdleSync();return supportingOwner(type);
 }
 private void supportingCapture(String name)throws Exception{
  CountDownLatch committed=new CountDownLatch(1);View[] window={null};long end=SystemClock.elapsedRealtime()+5000;
  while(window[0]==null&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{Activity owner=visibleActivity;if(owner==null||owner.isFinishing()||owner.isDestroyed())return;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(c.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.isHardwareAccelerated()){assertNull("Exactly one focused owned application window",window[0]);window[0]=root;}if(window[0]!=null){window[0].getViewTreeObserver().registerFrameCommitCallback(committed::countDown);window[0].invalidate();}});if(window[0]==null)SystemClock.sleep(25);}
  assertNotNull("Actual supporting Activity or help window",window[0]);assertTrue("Supporting frame committed",committed.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(ui.takeScreenshot(new File(folder,"nap-support-"+name+".png")));
 }
 private void supportingRow(Activity owner,String title,String subtitle,String frame)throws Exception{
  find(title);boolean[] ready={false};long end=SystemClock.elapsedRealtime()+5000;
  while(!ready[0]&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{assertSame("Same real destination",owner,visibleActivity);View root=owner.getWindow().getDecorView(),label=nativeText(root,title);if(label==null||!label.isLaidOut())return;View row=(View)label.getParent().getParent();if(!row.isEnabled()||!row.isAttachedToWindow())return;row.requestRectangleOnScreen(new Rect(0,0,row.getWidth(),row.getHeight()),true);ready[0]=true;});if(!ready[0])SystemClock.sleep(25);}
  assertTrue("Enabled supporting route: "+title,ready[0]);i.waitForIdleSync();
  i.runOnMainSync(()->{View root=owner.getWindow().getDecorView(),label=nativeText(root,title),copy=nativeText(root,subtitle);assertNotNull(title,label);assertNotNull(subtitle,copy);View row=(View)label.getParent().getParent();Rect titleBounds=new Rect(),copyBounds=new Rect(),rowBounds=new Rect();assertTrue(label.getGlobalVisibleRect(titleBounds));assertTrue(copy.getGlobalVisibleRect(copyBounds));assertTrue(row.getGlobalVisibleRect(rowBounds));assertTrue("Explanation below title: "+title,copyBounds.top>=titleBounds.bottom);assertEquals("Shared full-width leading edge",titleBounds.left,copyBounds.left);assertTrue("Whole 48dp+ clickable route: "+title,row.isClickable()&&row.isEnabled()&&rowBounds.height()==row.getHeight()&&rowBounds.width()==row.getWidth()&&rowBounds.height()>=Design.dp(c,48));assertTrue("Explanation inside route",rowBounds.contains(copyBounds));});supportingCapture(frame);
 }
 private void supportingBack(Class<? extends Activity> type)throws Exception{ui.pressBack();i.waitForIdleSync();supportingOwner(type);}
