 @Test public void scheduleListAndErrorRetryUseSavedDeadlineWithoutRealDelivery()throws Exception{try(Fixture f=new Fixture()){try{launch(0);click("Add schedule entry");text("Schedule nap");capture("schedule");UiObject2 date=ui.wait(Until.findObject(By.desc("Nap start date")),3000);assertNotNull(date);date.setText("2020-01-01");UiObject2 action=ui.findObjects(By.text("Schedule nap")).stream().filter(ViewObject->ViewObject.isClickable()).findFirst().orElseThrow();action.click();text("Choose a future start date and time.");capture("schedule-error");date=ui.wait(Until.findObject(By.desc("Nap start date")),3000);date.setText(Instant.ofEpochMilli(f.clock.wall).atZone(ZoneId.systemDefault()).toLocalDate().plusDays(1).toString());ui.findObjects(By.text("Schedule nap")).stream().filter(UiObject2::isClickable).findFirst().orElseThrow().click();text("Cancel nap");Alarm saved=f.nap();assertTrue(saved.nap.startWall>f.clock.wall);assertEquals(saved.nap.deadlineWall()-f.clock.wall,f.delay);capture("scheduled");click("Cancel nap");click("Multiple naps");text("Multiple naps");i.runOnMainSync(()->{View title=nativeText(activity.getWindow().getDecorView(),"Saved nap profiles"),subtitle=nativeText(activity.getWindow().getDecorView(),"One-date timers or weekly wake alarms");assertNotNull("Profile route title",title);assertNotNull("Profile route explanation",subtitle);View route=(View)title.getParent().getParent();Rect titleBounds=new Rect(),subtitleBounds=new Rect(),routeBounds=new Rect();assertTrue(title.getGlobalVisibleRect(titleBounds));assertTrue(subtitle.getGlobalVisibleRect(subtitleBounds));assertTrue(route.getGlobalVisibleRect(routeBounds));assertTrue("Explanation belongs below the title",subtitleBounds.top>=titleBounds.bottom);assertEquals("Full-width title and explanation share the leading edge",titleBounds.left,subtitleBounds.left);assertTrue("Profile route remains fully visible and tappable",route.isClickable()&&routeBounds.height()==route.getHeight()&&routeBounds.height()>=Design.dp(c,48));assertTrue("Explanation remains inside its actual route",routeBounds.contains(subtitleBounds));});capture("list");click("New nap");f.access="Allow Alarms & reminders before starting a nap.";click("Start nap");text(f.access);capture("permission-error");assertEquals(1,f.schedules);f.access="";f.scheduleFail=true;click("Start nap");text("Nap saved, but scheduling failed. Check alarm access and retry.");capture("scheduler-error");Alarm failed=f.nap();f.clock.wall+=1000;f.clock.elapsed+=1000;f.scheduleFail=false;click("Retry scheduling");awaitNap(f,a->a.nap.nonce.equals(failed.nap.nonce)&&a.nap.error.isEmpty(),"retry reconciled same timer");assertEquals(failed.nap.nonce,f.nap().nap.nonce);assertEquals(1199000,f.delay);assertEquals("",f.nap().nap.error);capture("retry");assertEquals(0,f.fires);supportingNavigation(f);}catch(Exception|AssertionError failure){captureFailure(failure);throw failure;}}}
 @Test public void strictPortableMetadataRestoreAndNonceCleanupPreserveUnrelatedData()throws Exception{try(Fixture f=new Fixture()){Alarm draft=new Alarm(0);draft.smartWindow=0;Alarm nap=Naps.start(c,draft,20,0,true);JSONObject valid;try(Store store=new Store(c,f.database)){valid=store.backup();}JSONObject invalid=new JSONObject(valid.toString());JSONObject raw=invalid.getJSONArray("alarms").getJSONObject(1).getJSONObject("nap");raw.put("minutes",20.5);try(Store store=new Store(c,f.database)){String before=store.backup().toString();assertThrows(JSONException.class,()->Backup.restoreData(store,invalid));assertEquals(before,store.backup().toString());Alarm malformed=Alarm.read(invalid.getJSONArray("alarms").getJSONObject(1));assertTrue(malformed.napInvalid);assertEquals(raw.toString(),malformed.json().getJSONObject("nap").toString());Backup.restoreData(store,valid);Alarm restored=store.alarm(nap.id);assertFalse(restored.enabled);assertEquals(NapPlan.Phase.CANCELLED,restored.nap.phase);assertEquals(nap.nap.nonce,restored.nap.nonce);}
  Naps.receive(c,nap.id,nap.nap.nonce);assertEquals(0,f.fires);Alarm restart;try(Store store=new Store(c,f.database)){restart=store.alarm(nap.id);}restart=Naps.start(c,restart,10,0,true);String fresh=restart.nap.nonce;assertNotEquals(nap.nap.nonce,fresh);Naps.dismissed(c,nap,false);assertEquals(fresh,f.nap().nap.nonce);f.clock.wall+=600000;f.clock.elapsed+=600000;Naps.receive(c,restart.id,fresh);assertEquals(1,f.fires);Naps.receive(c,restart.id,fresh);assertEquals(1,f.fires);Alarm active=f.nap();Naps.dismissed(c,active,true);assertEquals(NapPlan.Phase.FINISHED,f.nap().nap.phase);WakeCheckState check=WakeCheckState.waiting(UUID.randomUUID().toString(),"private-run",active.json().toString(),active.label,active.id,60000,false,new WakeCheckState.Clock(){public long wall(){return f.clock.wall;}public long elapsed(){return f.clock.elapsed;}public long boot(){return 4;}});Naps.confirmed(c,check);try(Store store=new Store(c,f.database)){assertNull(store.alarm(active.id));assertEquals(f.sentinelJson,store.alarm(1).json().toString());}i.runOnMainSync(()->Naps.activeTracking=()->true);launch(0);desc("Smart wake-up");click("Start nap");Alarm smart=awaitNap(f,a->a.enabled&&a.smartWindow==5&&a.nap.phase==NapPlan.Phase.PENDING,"smart timer admitted");assertEquals(5,smart.smartWindow);assertFalse(Naps.movement(c,smart,.5,2,30));f.clock.wall+=900000;f.clock.elapsed+=900000;assertFalse(Naps.movement(c,smart,.5,1,30));assertTrue(Naps.movement(c,smart,.5,2,30));assertEquals(2,f.fires);Naps.dismissed(c,f.nap(),false);try(Store store=new Store(c,f.database)){assertNull(store.alarm(smart.id));}}}
